export interface FieldError {
  field: string;
  message: string;
}

export interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
}

export type ParsedSubmission =
  | { ok: true; value: Submission; key: string | undefined; payload: string }
  | { ok: false; fields: FieldError[] };

const KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;
const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
/** Bodies larger than this are rejected without parsing. */
export const MAX_BODY_BYTES = 64 * 1024;

function integerField(obj: Record<string, unknown>, name: 'steps' | 'failAttempts', min: number, max: number, fallback: number, errors: FieldError[]): number {
  const v = obj[name];
  if (v === undefined) return fallback;
  if (typeof v !== 'number' || !Number.isInteger(v) || v < min || v > max) {
    errors.push({ field: name, message: `must be an integer from ${min} to ${max}` });
    return fallback;
  }
  return v;
}

/** Validates a submission's headers and raw body. `rawBody` is null when the body was too large. */
export function parseSubmission(contentType: string | undefined, rawBody: string | null, idempotencyKey: string | undefined): ParsedSubmission {
  const fields: FieldError[] = [];
  let key: string | undefined;
  if (idempotencyKey !== undefined) {
    if (KEY_PATTERN.test(idempotencyKey)) key = idempotencyKey;
    else fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  const mediaType = contentType?.split(';')[0]?.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
    return { ok: false, fields };
  }
  if (rawBody === null) {
    fields.push({ field: 'body', message: `body must be at most ${MAX_BODY_BYTES} bytes` });
    return { ok: false, fields };
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(rawBody);
  } catch {
    fields.push({ field: 'body', message: 'body must be valid JSON' });
    return { ok: false, fields };
  }
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    fields.push({ field: 'body', message: 'body must be a JSON object' });
    return { ok: false, fields };
  }

  const obj = parsed as Record<string, unknown>;
  for (const name of Object.keys(obj)) {
    if (!ALLOWED_FIELDS.has(name)) fields.push({ field: name, message: 'unknown field' });
  }

  const input = obj.input;
  if (input === undefined) {
    fields.push({ field: 'input', message: 'is required' });
  } else if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'must be a string' });
  } else if (input.length < 1 || input.length > 1000) {
    fields.push({ field: 'input', message: 'must be 1 to 1000 characters' });
  } else if (input.trim() === '') {
    fields.push({ field: 'input', message: 'must not be blank' });
  }

  const steps = integerField(obj, 'steps', 1, 20, 5, fields);
  const failAttempts = integerField(obj, 'failAttempts', 0, 5, 0, fields);

  if (fields.length > 0 || typeof input !== 'string') return { ok: false, fields };
  const value = { input, steps, failAttempts };
  return { ok: true, value, key, payload: JSON.stringify([input, steps, failAttempts]) };
}

