import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import { Store } from './store.ts';
import { MAX_BODY_BYTES, parseSubmission, type FieldError } from './validation.ts';

const db = openDatabase();
const store = new Store(db);
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[], headers?: Record<string, string>): void {
  send(res, status, { error: fields ? { code, message, fields } : { code, message } }, headers);
}

function methodNotAllowed(res: ServerResponse, allow: string): void {
  sendError(res, 405, 'method_not_allowed', `Method not allowed. Allowed: ${allow}.`, undefined, { allow });
}

function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', () => resolve(null));
  });
}

async function createJobFromRequest(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const rawBody = await readBody(req);
  const header = req.headers['idempotency-key'];
  const parsed = parseSubmission(req.headers['content-type'], rawBody, typeof header === 'string' ? header : undefined);
  if (!parsed.ok) {
    return sendError(res, 400, 'invalid_request', 'The request is invalid.', parsed.fields);
  }

  if (parsed.key !== undefined) {
    const existing = store.findByKey(parsed.key);
    if (existing) {
      if (existing.payload === parsed.payload) return send(res, 200, existing.job);
      return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    }
  }

  const { input, steps, failAttempts } = parsed.value;
  const job = store.createJob(input, steps, failAttempts, parsed.key ?? null, parsed.key !== undefined ? parsed.payload : null);
  send(res, 201, job, { location: `/api/jobs/${job.id}` });
}

function handle(req: IncomingMessage, res: ServerResponse): void {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    return send(res, 200, { status: 'ok', worker: store.workerUp(Date.now()) ? 'up' : 'down' });
  }

  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (pathname === '/api/jobs') {
    if (method === 'GET') return send(res, 200, { jobs: store.listJobs() });
    if (method === 'POST') {
      createJobFromRequest(req, res).catch(() => {
        if (!res.headersSent) sendError(res, 500, 'internal_error', 'Unexpected server error.');
      });
      return;
    }
    return methodNotAllowed(res, 'GET, POST');
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return sendError(res, 404, 'not_found', 'No such job.');
    }
    const job = store.getJob(id);
    return job ? send(res, 200, job) : sendError(res, 404, 'not_found', 'No such job.');
  }

  sendError(res, 404, 'not_found', 'No such route.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  try {
    handle(req, res);
  } catch {
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Unexpected server error.');
  }
});

server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeIdleConnections();
  setTimeout(() => process.exit(0), 2_000).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

