import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import { Store } from './store.ts';

/** Time for one simulated processing step. */
const STEP_MS = 100;
const HEARTBEAT_MS = 1_000;
const IDLE_POLL_MS = 200;
const ERROR_BACKOFF_MS = 500;
/** Retry delay is drawn from this range (inclusive of the lower bound, exclusive of the upper). */
const RETRY_MIN_MS = 250;
const RETRY_MAX_MS = 2_000;

const db = openDatabase();
const store = new Store(db);
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

/** Processes one attempt of the oldest eligible job. Returns false when there was nothing to do. */
async function processNext(): Promise<boolean> {
  const job = store.claimNext(Date.now());
  if (!job) return false;

  if (job.attempt <= job.failAttempts) {
    // Simulated transient failure at the first step, before any progress.
    await sleep(STEP_MS);
    const retryAt = Date.now() + RETRY_MIN_MS + Math.floor(Math.random() * (RETRY_MAX_MS - RETRY_MIN_MS));
    store.finishFailedAttempt(job.id, job.attempt, retryAt);
    return true;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return true; // Left running; the next start requeues it.
    store.reportProgress(job.id, job.attempt, step);
  }
  store.finishCompleted(job.id, job.attempt, job.input.toUpperCase());
  return true;
}

const recovered = store.recoverInterrupted(Date.now());
if (recovered > 0) console.log(`requeued ${recovered} interrupted job(s)`);
store.writeHeartbeat(Date.now());
const heartbeat = setInterval(() => store.writeHeartbeat(Date.now()), HEARTBEAT_MS);

console.log('worker started');
while (!stopping) {
  try {
    if (await processNext()) continue;
  } catch (e) {
    console.error(`worker error: ${e instanceof Error ? e.message : String(e)}`);
    await sleep(ERROR_BACKOFF_MS);
    continue;
  }
  await sleep(IDLE_POLL_MS);
}

clearInterval(heartbeat);
store.clearHeartbeat();
db.close();
console.log('worker stopped');

